def main():
    seen = {}
    services = []
    for row in RAW:
        code, title, official, sits, ecp, no_id, org, term, cost, fmt = row
        if code in seen:
            continue
        seen[code] = True
        slug = code.replace("/", "-").replace(" ", "")
        services.append({
            "id": slug,
            "code": code,
            "title": title,
            "official": official,
            "situations": sits,
            "ecp": ecp,
            "noId": no_id,
            "org": ORGS[org],
            "result": {"term": term, "cost": cost, "format": fmt},
            "steps": [
                "Проверьте, что данные о вас подтянутся из реестров — вручную заполнять нужно только недостающее.",
                "Заполните форму. Черновик сохраняется сам, можно закрыть вкладку и вернуться.",
                "Отправьте заявление. Статус появится в «Мои услуги» (раздел — в следующем этапе).",
            ],
        })

    payload = {
        "services": services,
        "situations": SITUATIONS,
        "quickActions": QUICK,
        "synonyms": SYNONYMS,
        "totalOfficial": 174,
    }
    out = Path("js/data.js")
    out.parent.mkdir(exist_ok=True)
    out.write_text(
        "window.EPASLUGA_DATA = " + json.dumps(payload, ensure_ascii=False, indent=2) + ";\n",
        encoding="utf-8",
    )
    print(f"wrote {len(services)} services")


if __name__ == "__main__":
    main()
